    body: "ルドルフ・シュタイナー（1861-1925）はオーストリア出身の思想家で、自ら提唱した「人智学（アントロポゾフィー）」と呼ばれる独自の世界観・人間観に基づく教育思想を展開しました。1919年、ドイツのタバコ工場「ヴァルドルフ・アストリア社」の経営者の依頼を受け、従業員の子弟のための学校を開設したことから、この教育法は「ヴァルドルフ教育」あるいは創始者の名にちなみ「シュタイナー教育」と呼ばれています。\n\n人間の心身の発達を約7年ごとの周期でとらえ、幼児期（0〜7歳）には模倣と遊びを、児童期（7〜14歳）には教師との情緒的な結びつきと絵画・音楽・オイリュトミー（身体表現）といった芸術的な体験を、青年期（14〜21歳）には抽象的・論理的な思考力の発達を重視するなど、発達段階に応じた独自の教育課程を組み立てる点が大きな特徴です。成績による早期の選抜や、知識の詰め込みを避ける姿勢も一貫しています。\n\n現在、世界各国にヴァルドルフ学校が設立されており、公教育の標準的な教育課程とは異なる理念に基づくオルタナティブ教育の代表例として、教育学の研究対象にもなっています。",
