    body: "大正自由教育運動（新教育運動・教育改造運動とも呼ばれる）は、19世紀末以降に欧米諸国で広がった新教育運動の思想が日本に輸入され、1920年代を中心に展開された教育改革の運動です。第一次世界大戦前後の大正デモクラシーの風潮を背景に、画一的で詰め込み型だった明治期以来の学校教育のあり方への批判が高まる中で発展しました。\n\n1917年に澤柳政太郎が創設した成城小学校や、1921年に羽仁もと子が創設した自由学園などが実践の主要な拠点となり、児童の興味・関心を出発点とする学習や、一人ひとりの個性を伸ばす柔軟な教育方法が積極的に試みられました。1921年に開催された「八大教育主張講演会」では、及川平治や小原國芳ら8名の教育者がそれぞれの新教育論を発表し、3000名を超える聴衆を集める大きな反響を呼びました。\n\nしかし1930年代に入り、国家による教育統制が強まる中でこの運動は次第に衰退していきました。それでも、児童中心・個性尊重という理念は、戦後の新教育や今日のアクティブラーニング、個別最適な学びの思想的な源流の一つとして評価されています。",
