    body: "開発主義教育（開発教授）とは、明治初期の日本に導入された教授理論・教授方法を指します。アメリカから招かれた教育者M・スコットらを通じてペスタロッチの直観教授の思想がもたらされ、東京師範学校の初代校長を務めた諸葛信澄らの著作を通じて全国の師範学校・小学校に広められました。\n\n「開発」とは、子どもの内部にすでに備わっている認識能力を外から刺激して引き出し、発達させるという意味です。教師が知識を一方的に教え込むのではなく、実物や単語図・連語図といった絵図を用いながら、教師と子どもとの問答を積み重ねることで理解を深めさせる方法がとられました。これは、それまでの素読・暗誦を中心とした伝統的な教授法からの大きな転換を意味するものでした。\n\nもっとも、実際の授業では型どおりの問答の反復に陥りやすいという課題も指摘され、明治後期にはヘルバルト学派による五段階教授法にその主流の座を譲っていきます。それでも、子どもの主体的な認識過程を重視するこの発想は、日本における近代的な授業観の出発点の一つとして位置づけられています。",
