    body: "実学主義とは、抽象的な観念や形式的な教養よりも、実際の生活や社会の中で役立つ知識・技術を身につけることを重視する教育思想・態度を指します。西洋近代教育史においては、コメニウスの汎知学やロックの経験論以降、自然科学的な知識や実用的な技能を教育内容に積極的に取り入れようとする流れの中に位置づけることができます。\n\n日本では特に、明治期の啓蒙思想家である福澤諭吉が『学問のすゝめ』の中で示した実学論がよく知られています。福澤は、当時重んじられていた和学・漢学を、実際の生活には役立たない「虚学」であると批判し、数理学（自然科学）と独立心を核とする「人間普通日用に近き実学」こそが学ぶべき学問であると説きました。実学によって一人ひとりが経済的・精神的に自立し、その積み重ねが国家の独立につながるという「一身独立して一国独立す」という理念を掲げた点が大きな特徴です。\n\nこの実学主義の発想は、後の職業教育・実業教育の重視や、生活経験に根ざした学びを大切にする教育実践にも通じる、日本の近代教育思想の重要な源流の一つとされています。",
