    body: "批判的教育学（クリティカル・ペダゴジー）は、パウロ・フレイレの『被抑圧者の教育学』を大きな源流とし、1970年代以降、主にアメリカでヘンリー・ジルーやピーター・マクラーレンらによって理論的に発展させられた教育思想の潮流です。学校を政治的に中立な場とはみなさず、既存の社会構造や権力関係を再生産する装置として批判的にとらえる点に大きな特徴があります。\n\nこの立場では、学校で教えられる教育内容やカリキュラムの背後に、特定の階層・人種・ジェンダーに有利にはたらく価値観が「隠れたカリキュラム」として組み込まれていることを問題視します。そのうえで、教師と学習者が上下関係のない対等な対話を重ねることを通じて、自らが置かれている社会状況を批判的に読み解く力（批判的リテラシー）を育み、不平等な構造の変革に主体的に関わっていく力を養うことを教育の目標とします。\n\n批判的教育学の視点は、多文化教育やシティズンシップ教育、教育格差研究など、教育を社会的公正の問題として捉え直そうとする現代の教育学のさまざまな領域に大きな影響を与え続けています。",
