    body: "実存主義教育とは、キルケゴール、ヤスパース、サルトルらの実存主義哲学を思想的背景とし、一般的・抽象的な「人間」ではなく、一回限りの人生を生きるかけがえのない個としての自己のあり方を教育の中心に据えようとする立場です。既存の価値や規範を上から一方的に伝達する教育よりも、学習者が自ら選び取り、自らの生き方に責任を負う主体として成長していく過程そのものを重視します。\n\nドイツの教育哲学者オットー・フリードリヒ・ボルノーは、実存主義の知見を教育学に積極的に取り入れ、日々の着実な積み重ねからなる訓育・陶冶の過程（連続的教育）だけでなく、危機や出会い、覚醒といった非連続的な瞬間を通じて人間が大きく変容していく側面（非連続的教育の形式）にも目を向けるべきだと論じました。また、ユダヤ人思想家マルティン・ブーバーが説いた「我と汝」という対話的関係論も、教師と子どもの人格的な出会いを重視する教育論として、この思想的な系譜に位置づけられています。\n\nこうした思想は、知識や技能の効率的な伝達だけでは捉えきれない、教育における人格的な出会いや自己形成の側面に光を当てるものとして、後の教育人間学の展開にも受け継がれています。",
