    body: "ヘルバルトは著書『一般教育学』の中で、授業を「明瞭・連合・系統・方法」という四つの段階を踏んで進める教授理論を提唱しました。この考え方を弟子のツィラーが「分析・総合・連合・系統・方法」という五段階に整理し直し、さらに後継者のラインが「予備・提示・比較（連合）・総括（系統）・応用（方法）」という、より実践的でわかりやすい五段階教授法へと発展させました。\n\n「予備」の段階では既習事項を振り返って新しい学習への興味を喚起し、「提示」で新しい教材を示し、「比較」で既有の知識と結びつけながら理解を深め、「総括」で学んだ内容を整理して一般的な法則や概念へとまとめ上げ、「応用」でそれを新しい問題場面に活用させる、という一連の流れで一時間の授業を構成します。\n\nこの理論は明治後期の日本に本格的に導入され、それまで主流だった開発主義教育に代わって全国の師範学校・小学校の標準的な授業方法となりました。段階を踏んで系統的に授業を組み立てるという発想は、今日の学習指導案における「導入・展開・まとめ」という基本構造にも色濃く受け継がれています。",
