    summary:
      "大正・昭和期を代表する教育者。「全人教育」を提唱して玉川学園を創立し、真・善・美・聖などの価値を人格の中で調和的に発達させることをめざす教育理念を掲げたことで広く知られている人物である。",
    body: "小原國芳（1887-1977）は鹿児島県出身の教育者で、京都帝国大学で教育学を専攻して学んだ後、教員生活を経て、大正自由教育の拠点であった成城小学校の主事として、児童の個性と自発性を尊重する新教育の実践に指導者として深く携わりました。\n\n1921年に開催された「八大教育主張講演会」で、小原は自らの教育理念として「全人教育」を提唱しました。これは、学問（知育）・道徳（徳育）・芸術（美育）・宗教（聖育）・身体（体育）・生活（実際生活の技術）という人間のさまざまな側面を、人格の中で偏りなく調和的に発達させ、真・善・美・聖・健・富といった価値を統合的に実現しようとする教育理念です。\n\n1929年には、自らが理想とする教育を一から実現するために玉川学園を創立し、幼稚園から大学院までを備える一貫総合学園へと発展させました。「全人教育」という言葉は今日では一般名詞としても広く使われるようになっており、知育だけに偏らない全人格的な成長を重んじる教育理念の代表例として、日本の教育史や教育思想の授業でも高く評価されています。",
