      "大正・昭和期の幼児教育研究者。フレーベル主義が形式化していた日本の幼稚園教育を批判し、子どもの自発的な生活を大切にする「誘導保育」を提唱した、「日本のフレーベル」とも呼ばれる人物である。",
    body: "倉橋惣三（1882-1955）は静岡県出身の児童心理学者・教育者で、東京帝国大学卒業後、東京女子高等師範学校（現在のお茶の水女子大学）附属幼稚園の主事を長年にわたり務め、日本における幼児教育の理論と実践の発展に大きく貢献しました。\n\n明治以来の日本の幼稚園教育は、フレーベルが考案した「恩物」と呼ばれる教具を型どおりに使わせる形式的な保育に陥りがちでした。倉橋はこうしたあり方を批判し、子どもが本来持っている「自ら生活し、自ら育とうとする力」を尊重しながら、保育者がその生活や遊びを適切な方向へと導いていく「誘導保育」という考え方を打ち出しました。子どもの自発的な活動を出発点とし、そこに保育者がさりげなく働きかけて経験を豊かにしていくという発想です。\n\n倉橋は附属幼稚園の保育者たちとともに「誘導保育案」を編み出しており、これは日本で最初期の体系的な保育カリキュラムの一つとされています。その理念は戦後まもなく作成された幼稚園教育要領にも影響を与え、遊びを通した学びを重視する現在の幼児教育の基本的な考え方の礎となっており、今日の保育者養成課程でも重要な内容として扱われています。",
