      "大正期の教育実践家。明石女子師範学校附属小学校の主事として、児童を小集団に分けて指導する「分団式動的教育法」を実践し、大正自由教育を代表する教育者の一人として広く知られるようになった。",
    body: "及川平治（1875-1939）は、1907年から約30年にわたって兵庫県の明石女子師範学校附属小学校の主事（校長）を務めた教育実践家です。画一的な一斉授業が学校教育の主流であった当時、児童一人ひとりの学習の進み方や興味・関心の違いに応じた指導のあり方を粘り強く模索しました。\n\nその代表的な実践が「分団式動的教育法」です。これは、学級全体を対象とする一斉指導だけに頼るのではなく、学習内容や児童の理解度に応じて学級を小さな集団（分団）に分け、「一斉・分団・個人」という指導形態を状況に応じて柔軟に組み合わせる方法です。児童の自発的な学習活動や児童同士の教え合いを重視し、教師から知識を静的に受け取るだけの学習ではなく、児童自身が能動的に学びを進めていく「動的教育」の実現をめざしました。\n\n明石女子師範学校附属小学校は、こうした実践によって大正自由教育を代表する学校の一つとして全国から注目を集めました。学級内での小集団編成や個に応じた指導という発想は、現代の習熟度別指導や個別最適な学びの考え方の先駆けとしても位置づけられています。",
