    summary:
      "子どもの日常生活における具体的な経験や身近な問題を学習の出発点とする教育思想・実践。大正自由教育や戦後初期の経験主義的なカリキュラム編成に広く見られる、生活と学びを結びつける考え方である。",
    body: "生活教育とは、教科書に書かれた知識を抽象的な形で教え込むのではなく、子どもが実際の生活の中で出会う経験や具体的な問題を学習の出発点とし、そこから知識・技能・態度を総合的に育てていこうとする教育の考え方です。デューイの経験主義や問題解決学習の思想を理論的な背景の一つとしつつ、日本では大正自由教育運動の中で、児童の生活経験を尊重する実践として各地の学校で試みられました。\n\n第二次世界大戦後には、アメリカの新教育の考え方も取り入れられ「コア・カリキュラム」運動が各地に広がりました。子どもの生活そのものを学習の中心課程（コア）に据え、そこから理科や社会科など各教科の系統的な学習内容を有機的に関連づけていく試みが行われ、これは生活教育の理念を学校のカリキュラム全体を通じて実現しようとする代表的な取り組みでした。\n\nもっとも1950年代以降、学力の系統性を軽視しているという批判が高まり、教育課程の重点は系統学習を重視する方向へと移っていきます。それでも、子どもの生活経験に根ざした学びを大切にする発想は、今日の総合的な学習の時間や小学校低学年の生活科などに確かな形で受け継がれています。",
