    summary:
      "子どもが自らの生活の中で見聞きし、感じ、考えたことをありのままの言葉で文章に綴らせる作文教育の実践・運動。昭和初期の東北地方を中心に全国へ広がり、大きな社会的反響を呼んだ民間教育運動である。",
    body: "生活綴方は、子どもが自分の日々の生活の中で経験した事実や、そこで感じたこと・考えたことを、飾らない自分自身の言葉で正直に文章に綴らせる作文教育の実践、およびそれを民間で推し進めた教育運動を指します。単に美しく整った文章を書く技術を教えるのではなく、ものごとをじっくりと見つめ、筋道立てて考える力そのものを育てることを目的としてきた点に大きな特徴があります。\n\n1929年に雑誌『綴方生活』が創刊されたことなどをきっかけに、生活綴方は民間教育運動として全国へと広がりました。とりわけ冷害や貧困に苦しんでいた東北地方では、子どもたちが自らの厳しい生活の実態をありのままに綴った作文が数多く生み出され、社会の現実を見つめさせる教育実践として大きな注目を集めました。書かれた作品は学級文集にまとめられ、学級全体で読み合い語り合う過程を通じて、子ども同士の共感や連帯感を育む役割も果たしました。\n\nこの運動は戦時体制の強化とともに弾圧を受けて衰退しましたが、戦後まもなく無着成恭の『山びこ学校』などをきっかけに再評価され、生活現実に根ざした国語教育・作文教育の重要な系譜として、今日も教育実践研究の対象とされています。",
