    body: "教育人間学（教育学的人間学）とは、教育という営みを単なる技術や制度の問題としてだけではなく、「人間とは何か」という哲学的・人間学的な問いと結びつけながら、その根本から捉え直そうとする教育学の一分野です。哲学・宗教・文学・文化・社会といった多様な領域との関わりの中で、教育における行為・関係・支援・発達といったテーマを幅広く扱います。\n\nこの分野に特に大きな影響を与えたのが、ドイツの教育哲学者オットー・フリードリヒ・ボルノーです。ボルノーはキルケゴール、ハイデガー、ヤスパースらの実存主義哲学の知見を教育学に積極的に取り入れ、日々の着実な積み重ねとしての「連続的教育」だけでなく、危機や出会い、覚醒といった人間の実存にとって決定的な意味を持つ「非連続的な」契機にも目を向ける必要があると論じました。\n\n日本では1970年代後半以降、ボルノーらの著作の翻訳・紹介を通じて教育人間学への関心が高まりました。発達段階や学習効率といった量的な指標だけでは捉えきれない、教育における人格的な出会いや意味の次元を問い直す視点として、今日の教育学研究にも一定の影響を与え続けています。",
