    body: "澤柳政太郎（1865-1927）は、明治・大正期を代表する教育者・教育行政家です。文部官僚として文部次官などの要職を歴任し、小学校の義務教育年限の延長や授業料の無償化、東北帝国大学における日本で初めての女子学生の入学許可など、近代日本の教育制度の整備に多大な貢献をしたことから「日本教育界の父」とも称されています。教育調査会の委員としても活動しました。\n\n文部省を退官した後、澤柳は自らの理想とする教育を実験的に追求するため、1917年に私立の成城小学校を創設し、自ら校長に就任しました。ここでは画一的な一斉教授にとどまらず、児童一人ひとりの個性や自発性を尊重する新しい教育方法が積極的に試みられ、成城小学校は大正自由教育運動を代表する実践校として全国の教育関係者から広く注目を集めました。\n\n澤柳は、教育を単なる経験や勘に頼って行うのではなく、心理学など実証的な科学の知見に基づいて研究し改善していくべきだという立場も強く持っており、この姿勢は「教育の科学化」を志向する日本の教育学研究の発展にも少なからぬ影響を与えました。",
