    body: "ヨハン・フリードリヒ・ヘルバルト（1776-1841）はドイツの哲学者で、倫理学と心理学を基礎に教育学を体系化しようとしました。教育の目的を倫理学に、教育の方法を心理学に求めるという考え方は、教育学を独立した学問として確立する上で大きな役割を果たしました。\n\n授業を「明瞭・連合・系統・方法」の4段階（後に弟子によって5段階に発展）で構成する教授法を提唱し、これは後に「五段階教授法」として世界中に広まりました。\n\nヘルバルトの思想は明治期の日本にも輸入され、当時の授業方法や教員養成に大きな影響を与えました。「陶冶」と「訓育」を区別する教育学の伝統的な整理も、ヘルバルト学派の議論に由来します。",
