    body: "大村はま（1906〜2005）は東京女子大学卒業後、長野県の高等女学校教員を経て、戦後は新制中学校の国語科教師として1980年まで73歳10か月にわたり現場に立ち続けた実践家です。理論を先に立てるのではなく、日々の教室での実践の中から自らの教育思想を練り上げていったことが特徴で、単なる技術者ではなく、子どもの学びを見つめ続ける「哲学する実践者」として位置づけられています。\n\n大村の教育思想の核心は、新聞や雑誌の切り抜きなど生きた教材を用いて一人ひとりの実態に応じた課題を用意する「大村単元学習」と、綴ること・書くことの指導を通じて子どもの思考力と自己学習力を育てるという実践理念にあります。彼女は「教えることは学び続けることである」という信念を持ち、退職後90歳を超えてもなお新しい単元を創り続け、教師自身が学習者であり続ける姿勢を貫きました。既製の教科書や指導書に頼らず、常に子どもの実態から出発する授業づくりを重視した点も特徴です。\n\n大村はまの思想は、実践に根ざした教師の専門性や、教師自らが学び続ける「反省的実践家」としてのあり方を考える上で、今日の教師教育や授業研究に大きな示唆を与え続けています。単元学習や個に応じた教材づくりという発想は、現在の個別最適な学びの議論にも通じるものとして再評価されています。",
