    body: "アンドラゴジー（andragogy）は、ギリシャ語の「アネール（成人）」を語源とする成人教育の理論で、アメリカの成人教育学者マルカム・ノールズが体系化し普及させた概念です。子どもを対象とする教育学を意味する「ペダゴジー」に対置される形で用いられ、成人は子どもとは異なる学び方の特性を持つという前提に立って提唱されました。\n\nノールズは、成人学習者の特徴として、自己概念が自律的で自己主導的であること、豊富な経験が学習資源となること、社会的役割の変化に応じた学習へのレディネスを持つこと、学んだ知識をすぐに応用したいという課題中心の方向づけを持つこと、内発的な動機づけによって学ぶことなどを挙げました。これに基づき、成人教育では教師主導の一方的な講義よりも、学習者自身が目標設定や計画立案に参加する協働的な学習環境が重視されます。\n\nアンドラゴジーの考え方は、社会人向けのリカレント教育や企業内研修、生涯学習の設計など幅広い場面で応用されており、日本でも生涯学習社会の進展とともに注目されています。一方で、子どもと成人の学び方を截然と区別することへの批判もあり、両者を連続的なものとして捉え直す議論も進んでいます。",
