    title: "脱学校論（イリイチ）",
    reading: "だつがっこうろん",
    kana: "た",
    categories: ["philosophy"],
    summary:
      "思想家イヴァン・イリイチが1971年の著書『脱学校の社会』で展開した、学校制度そのものが人間の自主的な学びを阻害しているとする批判理論です。",
    body: "脱学校論は、オーストリア生まれの思想家イヴァン・イリイチ（1926〜2002）が1970年から71年にかけて刊行した『Deschooling Society（脱学校の社会）』で提唱した、近代学校制度に対する根本的な批判理論です。イリイチは、学校が知識や学歴を独占的に配分する制度となることで、社会全体が学校の価値基準に支配される「学校化された社会」を生み出していると指摘しました。\n\nイリイチによれば、学校教育は本来自由であるべき学びを、年齢別のカリキュラムや資格・卒業証書といった制度的な枠組みに閉じ込め、人々から自主的に学ぶ力を奪ってしまいます。彼はこの状態を批判し、代わりに学習者同士や地域の人的資源を結びつける「学習のためのネットワーク」を構想し、学校に依存しない多様な学びの回路を提案しました。この主張は同時代の管理社会批判や脱病院化社会論とも通底しています。\n\n脱学校論は当時大きな論争を呼び、学歴社会批判やオルタナティブ教育、ホームスクーリング運動などに影響を与えました。学校制度そのものの是非を問い直すこの視座は、不登校やフリースクール、近年の学びの多様化をめぐる議論においても、学校の役割を根本から考え直す手がかりとして参照され続けています。",
