    summary:
      "初代文部大臣として学校令を整備し、国家の発展に資する人材育成を教育の目的とする国家主義的教育思想を打ち立てた明治期の政治家・教育行政家です。",
    body: "森有礼（1847〜1889）は薩摩藩出身の政治家で、欧米への留学経験を持ち、初代アメリカ駐箚公使などを歴任した後、1885年の内閣制度発足に伴い初代文部大臣に就任しました。就任後は帝国大学令・師範学校令・小学校令・中学校令のいわゆる諸学校令を1886年に公布し、日本の近代学校制度の骨格を築いた人物として知られています。\n\n森は「学校はつまるところ国家のために設けられるものであり、生徒本人のためではなく国家のためのものであることを教育行政において常に念頭に置くべきである」という考えを基本方針とし、教育を国家の富強と発展に資する手段として位置づけました。これは後に「国体教育主義」とも呼ばれ、特に師範学校において軍隊式の集団訓練や規律を重視した点に色濃く表れています。戦後はこの国家主義的性格が批判の対象となりましたが、1960年代以降は啓蒙思想の到達点として彼の近代化構想を再評価する研究も進んでいます。\n\n森有礼が整備した学校体系や教育行政の仕組みは、その後の日本の学校教育制度の原型となり、国が教育に責任を持つという発想は現在の教育行政にも受け継がれています。一方で、教育を国家目的に従属させる思想は、教育の目的をめぐる根本的な問いを今日にも投げかけています。",
