    body: "プロジェクト・メソッドは、アメリカの教育学者ウィリアム・ヒアド・キルパトリック（1871〜1965）が1918年に発表した論文「The Project Method」で提唱した学習指導の理論です。キルパトリックはコロンビア大学でジョン・デューイに師事し、その経験主義・活動主義の思想を継承しながら、より具体的な指導方法として体系化しました。\n\nこの方法では、学習は子ども自身が主体的に目的を持つ活動としての「プロジェクト」を中心に組織されます。キルパトリックはプロジェクトの過程を、目的の設定、計画の立案、実行、そして結果の評価・判断という段階に整理し、子どもが自ら課題を見出し計画を立てて取り組み、その成果を振り返ることを通じて、知識や技能だけでなく態度や価値観までも統合的に学ぶことを重視しました。教科の枠にとらわれず、実生活に結びついた総合的な学習活動を組織する点が特徴です。\n\nプロジェクト・メソッドは新教育運動の中で世界的に広まり、日本の大正自由教育期の合科学習や単元学習にも影響を与えました。今日の総合的な学習の時間やプロジェクト型学習（PBL）にも通じる考え方であり、子どもの主体的な計画と実行を軸にした学びのモデルとして、その理論的意義が再評価されています。",
