    body: "ガブリエル・コンペレ（Gabriel Compayré、1843〜1913）は、フランスの教育学者・政治家です。高等師範学校を卒業後、トゥールーズ大学哲学教授、リヨン大学学長、文部省視学官、女子師範学校教授などを歴任し、教育理論と教育行政の双方に携わりました。1907年にはアカデミー会員にも選出されています。\n\nコンペレの教育理論の特徴は、教育を子どもの意志に対する大人からの意図的・計画的な働きかけと捉えつつ、その目的をあくまで子ども自身の身体的・知的・道徳的能力の自然な発達を助けることに置いた点にあります。彼はこうした教育の技法を確立するにあたって、当時発展しつつあった実験心理学や生理学による子どもの発達観察を重視し、思弁的な理論よりも実証的な子ども理解を教育学の基礎に据えようとしました。また代表作『十六世紀以降のフランス教育学説史』（1879年）は、フランスにおける教育思想の展開を体系的にまとめた重要な業績として知られています。\n\nコンペレの実証的・心理学的な教育理論は、教育学を経験科学として基礎づけようとする流れの一翼を担い、20世紀以降の児童研究や発達心理学に基づく教育論への橋渡しとなりました。子どもの発達段階に応じた指導という発想は、その後の教育心理学の発展にも受け継がれています。",
