    body: "人智学（独: Anthroposophie、英: anthroposophy）は、ギリシャ語の「アントロポス（人間）」と「ソフィア（叡智）」を語源とする言葉で、オーストリア出身の思想家ルドルフ・シュタイナー（1861〜1925）が創始した思想・運動を指します。シュタイナーは当初、神秘主義的な思想運動である神智学協会に深く関わっていましたが、1912年頃にこれと袂を分かち、人間を中心に据えた独自の思想体系である人智学を確立しました。\n\n人智学は、人間を身体・魂・霊の三層からなる存在として捉え、人間の発達段階に応じて霊的な成長を遂げていくという世界観に基づいています。人間は宇宙や自然界の縮図であり、両者は密接な相互関係のうちにあるとされ、こうした世界観から独自の子ども発達論が導かれました。シュタイナーはこの人智学的な人間観・発達観を教育に応用し、7年ごとの発達段階に応じた教育課程を組み立てるシュタイナー教育（ヴァルドルフ教育）を創始したほか、バイオダイナミック農法や人智学医学など、教育以外の多様な分野にもその思想を展開しました。\n\n人智学はシュタイナー教育の理論的な背景として、身体・感情・思考の調和的な発達を重視する教育観を支えており、日本を含む世界各国のシュタイナー学校の教育実践の根底に位置づけられています。科学的検証になじみにくい神秘主義的側面には批判もある一方、全人的な子ども理解を志向する点で、独自の教育思想史上の位置を占めています。",
