      "アマルティア・センとマーサ・ヌスバウムが発展させた、人が実際に「なりたい自分になれる自由」の幅を福祉や教育の評価基準とする理論です。",
    body: "ケイパビリティ・アプローチ（capability approach、潜在能力アプローチ）は、インドの経済学者アマルティア・センが1980年代に提唱し、その後アメリカの哲学者マーサ・ヌスバウムらによって発展させられた理論です。人間の福祉や豊かさを、所得や財の保有量だけで測るのではなく、人が実際に選び取ることのできる生き方や活動の幅、すなわち「ケイパビリティ（潜在能力）」によって捉え直そうとする立場です。\n\nこの理論では、財やサービスを所有していても、それを実際に活用して望む生き方を実現できる自由（機能を選び取る自由）がなければ真の豊かさとは言えないと考えます。センは、どのようなケイパビリティを重視すべきかは民主的な討議を通じて決めるべきだとする手続き的な立場をとったのに対し、ヌスバウムは生命・身体的健康・感覚と想像力と思考・遊びなど、普遍的に保障されるべき中心的なケイパビリティのリストをあらかじめ示す立場をとりました。教育はこうした潜在能力を開花させる「内的ケイパビリティ」を育む中心的な手段として位置づけられます。\n\nケイパビリティ・アプローチは、国連開発計画の人間開発指数（HDI）の理論的基盤となったほか、教育の目的を単なる学力向上や経済的有用性ではなく、一人ひとりが自分の望む生き方を選び取る自由の拡大に置く視点として、教育格差や特別支援教育、シチズンシップ教育などの議論に新たな観点を提供しています。",
