    summary:
      "教育それ自体に価値を見出す内在的目的と、教育を経済発展や国家形成など外部の目的達成の手段とみなす外在的目的とを区別する教育哲学上の枠組みです。",
    body: "教育の目的をめぐっては、伝統的に「内在的目的」と「外在的目的」という二つの立場が対比されてきました。内在的目的とは、教育や学問そのものに固有の価値を認め、知性の発達や真理の探究、人格の陶冶それ自体を教育の目的とみなす立場です。これに対し外在的目的とは、教育を経済成長や国家の発展、職業能力の育成といった、教育の外部にある別の目的を達成するための手段として位置づける立場を指します。\n\nイギリスの教育哲学者R・S・ピーターズは、著書『倫理学と教育』（1966年）などにおいて分析哲学の手法を用い、「教育」という概念そのものに内在する規範的・認知的基準を明らかにしようとしました。彼は、教育を単なる知識や技能の伝達（訓練）と区別し、望ましい価値のある内容を、学習者がその意義を理解する仕方で身につけさせる過程こそが教育の名に値すると論じ、教育に内在する価値を重視する立場をとりました。一方で、産業社会における人材育成の要請を強調する立場は、教育を経済発展の手段とみなす外在的目的論の代表例とされます。\n\nこの区別は、学力向上や経済的有用性を強調する政策と、人格形成や教養そのものを重視する理念との間で揺れ動く教育政策論争を整理する枠組みとして今日も参照されています。人的資本論やネオリベラリズムの教育論と、全人教育を掲げる立場との対立を理解する上でも、内在的目的と外在的目的という視座は重要な分析軸となっています。",
