    body: "ネオリベラリズム（新自由主義）は、政府の介入を最小限にとどめ、市場における自由な競争を通じて社会の効率性や質を高めようとする経済思想であり、1980年代以降イギリスやアメリカを中心に教育政策にも強い影響を与えるようになりました。教育の領域における新自由主義は、公共サービスとしての教育に競争原理や顧客としての保護者・子どもの選択を持ち込み、それによって教育の効率化と質的向上を図ろうとする考え方として展開されました。\n\n具体的な政策としては、学校選択制の導入、学力テストの結果公表や学校評価に基づく予算配分、公立学校の民営化やバウチャー制度、教員評価と処遇へのインセンティブの導入などが挙げられます。日本においても21世紀に入って以降、小中学校の学校選択制や、進学実績を競い合う公立中高一貫校の設置、教員評価制度の導入といった形で、こうした市場原理を取り入れた改革が進められてきました。\n\nこうした改革は学校間の切磋琢磨や説明責任の強化につながる一方で、地域間・学校間の格差の拡大や、教職の専門性・自律性の変容、点数競争によるカリキュラムの偏りなどの弊害も指摘されています。教育を市場の論理で捉えることの是非は、教育の公共性や平等をめぐる根本的な問いとして、今日も活発に議論され続けています。",
