    body: "ハーバート・スペンサー（1820〜1903）はイギリスの哲学者・社会学者で、進化論を社会現象の説明に応用した「社会進化論」で知られる思想家です。彼は1861年に刊行した著作『教育論――知育・徳育・体育』において、当時のイギリスで重んじられていた古典語学中心の教養主義的教育を批判し、実生活における有用性を基準とする新しい教育観を提示しました。\n\nスペンサーはこの著作で「どのような知識が最も価値があるか」という問いを立て、その答えを「科学」であると論じました。彼は人間の諸活動を、自己保存に直接関わる活動、生活に必要な物資を得るための活動、子どもを育てる活動、適切な社会的・政治的関係を維持する活動、余暇を充実させる活動の順に重要度を整理し、それぞれの活動において科学的知識が最も実用的な価値を持つと主張しました。あわせて、知育のみならず徳育・体育を含めた三育を教育の基本原理として提示した点も、その後の教育論に大きな影響を与えました。\n\nスペンサーの実用主義的・科学重視の教育論は、古典中心の教養主義から実学重視の近代的カリキュラムへの転換を促す思想的原動力の一つとなりました。知育・徳育・体育という三領域による教育目標の整理は、日本を含む近代学校教育の教育目標の立て方にも影響を及ぼしたとされています。",
