    body: "プラトン(紀元前427年頃-紀元前347年頃)は、古代アテナイの哲学者であり、ソクラテスの弟子として学び、後にアカデメイアを創設して教育活動を行った。主著『国家(ポリテイア)』において、プラトンは正義の実現した理想国家を論じ、その統治者には哲学的な知恵を備えた「哲人王」がふさわしいとした。哲人王を育成するには、幼少期からの音楽・体育による初期教育に始まり、数学・幾何学・天文学などの厳格な訓練を経て、最終的に弁証法によって「善のイデア」を認識するに至る長大な教育課程(30代半ばから50歳頃までの教育選抜)が必要であるとされた。\n\nプラトンにとって教育とは、単なる知識の伝達ではなく、魂を感覚的な世界から永遠不変のイデアの世界へと向け直す「魂の転換」であった。『国家』第7巻の「洞窟の比喩」はこの思想を象徴しており、洞窟の奥で影しか見ない囚人が外の光の世界(真実在)へと導かれる過程として教育を描いている。国家の存立そのものが教育に懸かっているという考えから、プラトンは教育を私事ではなく国家的な事業として位置づけ、能力に応じた選抜と専門化を通じて理想的な統治を実現しようとした。\n\nプラトンの教育思想は、その後の西洋教育史に絶大な影響を及ぼした。理性を陶冶することによって徳と知が一致するという知徳合一の理念、能力に応じた教育課程の分化という発想、そして教育を国家形成の中核に据える視点は、後世のアリストテレスやルネサンス期の人文主義教育、さらには近代の教育制度論にまで受け継がれている。",
