    body: "アリストテレス(紀元前384年-紀元前322年)は、プラトンの弟子であり、後にマケドニア王アレクサンドロス大王の家庭教師を務め、アテナイにリュケイオンを創設した哲学者である。主著『ニコマコス倫理学』において、人間にとっての最高善は幸福(エウダイモニア)であり、それは徳の発揮を伴う魂の活動によって実現されると論じた。徳は生得的なものではなく、正しい行為を反復して習慣づけることによって身につく性格的な資質であるとし、過剰と不足の両極端を避ける「中庸」の実践を重視した。\n\nアリストテレスはプラトンのイデア論的・観念的な教育観とは異なり、経験と習慣形成を通じた徳の獲得という、より経験主義的で実践的な人間形成論を展開した点に特徴がある。知性的徳(知恵・思慮など学習によって獲得される徳)と性格的徳(勇気・節制など習慣によって獲得される徳)を区別し、とりわけ具体的な状況で何が善であるかを見極めて適切に行為する実践知(フロネーシス)を重視したことは、後の徳倫理学および教育における人格形成論の基盤となった。\n\nまた『政治学』では、教育は国家の存続に不可欠な公共的営みであり、年齢段階に応じた身体・徳性・知性の教育を国家が制度として担うべきだと論じている。アリストテレスの思想は中世スコラ哲学やルネサンス期の人文主義教育に継承され、徳を習慣化された卓越性として捉える発想は、現代の徳倫理学に基づく人格教育論や道徳教育の理論的基盤としても再評価されている。",
