    body: "ソクラテス(紀元前469年頃-紀元前399年)は、古代アテナイの哲学者であり、著作を残さず、もっぱら街頭での対話を通じて自らの思想を展開したことで知られる。彼が用いた教育方法は「問答法」と呼ばれ、対話相手に次々と問いを投げかけることで、相手が自明だと思い込んでいた知識の矛盾に気づかせ、答えに窮する状態(アポリア)へと導く。この最初の段階は、相手の抱く思い込みや偏見を打ち砕くことから「エイロネイア(皮肉)」とも呼ばれる。\n\n問答法の第二段階は「産婆術(マイエウティケー)」と呼ばれる。ソクラテスは自身の母が助産婦であったことになぞらえ、教師の役割は知識を一方的に教え込むことではなく、あたかも産婆が出産を助けるように、学び手の内にすでに萌芽としてある考えを対話によって引き出し、自ら真理へと到達させる手助けをすることだと考えた。教師は答えを与える存在ではなく、相手自身の思考を触発し整理する媒介者として位置づけられる。\n\nこの方法論は、知識を外部から注入する伝達型の教育観とは対照的に、学習者自身の主体的な思考と気づきを重視する教育観の源流として、西洋の教育思想史において極めて大きな影響を及ぼしてきた。現代においても、発問を通じて児童生徒の思考を深める授業技術や、対話を通じた批判的思考力の育成、コーチングにおける傾聴・質問技法などに、ソクラテスの問答法の理念が受け継がれている。",
