    summary:
      "孔子に始まる儒教の教えに基づく教育思想。『論語』の「修己治人」を核に、人格の陶冶と社会秩序の実現を一体のものとして捉え、日本の近世教育に深い影響を与えた。",
    body: "儒教的教育思想は、中国春秋時代の思想家である孔子(紀元前551年頃-紀元前479年)に始まる儒教の教えを基盤とする教育観である。その中心原理は「修己治人」、すなわちまず自己の人格を修養し徳を身につけたうえで、その徳をもって他者や社会を治めるという考え方にある。『論語』『大学』『中庸』『孟子』の四書には、仁・義・礼・智・信といった徳目の涵養と、師弟間の人間的な信頼関係を通じた人格教育の理念が説かれており、単なる知識の習得ではなく、人格の完成そのものを教育の目的とする点に特徴がある。\n\n日本には古代に伝来した儒教が、とりわけ江戸時代に朱子学を中心として幕藩体制を支える教学として重んじられ、藩校や寺子屋における教育内容の中核をなした。修己治人の理念は、江戸時代の武士教育における自己鍛錬と統治者としての責務の一体化という形で受け継がれ、明治期以降も「修身」という教科名や教育勅語の徳目にその影響が色濃く残った。二宮尊徳や吉田松陰など近世日本の教育者の思想にも、儒教的な人格陶冶と実践重視の考え方が根底に流れている。\n\n儒教的教育思想は、知識偏重ではなく人格の完成を教育目的の中心に据える点で、西洋の主知主義的な教育観とは異なる系譜を形成してきた。他方で、身分秩序の固定化や画一的な徳目の押しつけにつながりやすいという批判も近代以降なされており、修己治人の理念をいかに民主的な人格教育として再解釈するかが、今日の道徳教育論においても論点となっている。",
