    body: "二宮尊徳(1787年-1856年)は、相模国(現在の神奈川県小田原市)の農家に生まれ、幼くして両親を失いながらも独学で学問を修め、荒廃した農村の復興に生涯を捧げた農政家・思想家である。彼が説いた「報徳思想」は、天地・君・親・人から受けた徳に報いることを基本理念とし、「至誠(誠実な心)」「勤労(勤勉な労働)」「分度(自らの分限をわきまえた生活設計)」「推譲(蓄えた余剰を将来や他者のために譲ること)」の四つを柱とする実践的な道徳・経済思想である。\n\n尊徳の教育思想の特色は、書物による学問よりも日々の労働や生活実践のなかに道徳を体得させようとした点にある。彼自身、昼は農作業に従事し、夜にわずかな灯りのもとで読書を重ねたという逸話に象徴されるように、勤労と学問を一体のものとして捉え、自らの生活を通じて周囲の人々を教化していった。晩年までに、報徳仕法の指導を行った地域は全国600か村以上に及んだと伝えられ、道徳と経済の両立という思想は、単なる精神論にとどまらず、実際の農村再建という具体的な社会実践として結実した。\n\n二宮尊徳の思想は、明治以降「報徳社」運動として全国に広がり、勤勉・倹約・互助を重んじる国民道徳の象徴として、薪を背負い本を読む「二宮金次郎像」とともに戦前の学校教育に取り入れられた。実践と労働を通じた人格陶冶という発想は、儒教的な修己治人の理念を土着的に発展させたものと位置づけられ、日本独自の教育思想史における重要な系譜をなしている。",
