    body: "中江兆民(1847年-1901年)は、土佐藩(現在の高知県)に生まれ、幕末から明治にかけて活動した思想家・政治家である。長崎や江戸でフランス語を学んだのち、1871年にフランスへ留学して西洋の政治思想を学び、帰国後は東京に仏学塾を開いてフランス流の学問・思想の普及に努めた。彼の最も重要な業績は、ジャン=ジャック・ルソーの『社会契約論』を漢文体で翻訳・注解した『民約訳解』であり、この訳業を通じて主権在民や社会契約の思想を日本に本格的に紹介したことから、後に「東洋のルソー」と評されるようになった。\n\n兆民の教育思想は、単なる翻訳・紹介にとどまらず、自由民権運動の理論的支柱として、国民一人ひとりが政治的主体としての自覚と教養を身につけることを重視した点に特徴がある。彼は人民が自らの権利を自覚し、理性的な議論を通じて政治に参加する能力を養うことこそが、近代国家における教育の要諦であると考え、これは官による上からの教化を重視した当時の国家主義的教育観とは一線を画するものであった。\n\n中江兆民の思想と実践は、明治期における啓蒙的知識人のあり方を示すとともに、西洋近代思想の翻訳と受容を通じて日本の近代教育思想の形成に大きく寄与した。ルソーの教育思想(消極教育・自然教育)そのものというよりも、その政治哲学を介して主権者教育・公民教育の理念を日本に根づかせた点に、兆民の教育史上の意義がある。",
