    body: "新渡戸稲造(1862年-1933年)は、陸奥国盛岡(現在の岩手県盛岡市)に生まれ、札幌農学校で学んだのちアメリカ・ドイツに留学し、農政学・農学を修めた教育者・思想家である。1900年に英文で著した『武士道(Bushido: The Soul of Japan)』は、宗教教育のない日本でいかに道徳が培われるかという欧米知識人からの問いに応えるために執筆されたもので、義・勇・仁・礼・誠といった武士の徳目を通じて日本人の倫理観を欧米世界に紹介し、ドイツ語やポーランド語をはじめ各国語に翻訳される国際的ベストセラーとなった。\n\n新渡戸は思想家としての活動にとどまらず、実際の教育行政にも深く関わった。東京女子大学の初代学長を務め、津田塾の顧問としても女子高等教育の充実に尽力するなど、近代日本における女子教育の発展に大きく貢献した。また第一高等学校校長や東京帝国大学教授を歴任し、国際連盟事務次長として国際教育協力にも携わるなど、日本と西洋を架橋する国際的な視野をもった教育者として活動した。\n\n新渡戸の思想は、日本古来の武士の道徳と西洋のキリスト教的人格主義とを統合しようとした点に特色があり、東西の文化を比較しつつ日本人の精神性を世界に発信するという姿勢は、比較教育・国際理解教育の先駆的な実践としても位置づけられる。旧五千円紙幣の肖像としても知られ、近代日本の国際的教育者の代表的人物である。",
