      "オーストリア生まれのユダヤ人哲学者(1878-1965)。主著『我と汝』において「我-汝」の対話的関係を人間存在の根源とし、対話を通じた全人格的な出会いを重視する教育観を提示した。",
    body: "マルティン・ブーバー(1878年-1965年)は、ウィーンに生まれたユダヤ人哲学者・宗教思想家である。フランクフルト大学で宗教学とユダヤ教倫理を講じたのち、1938年にナチス・ドイツを逃れてパレスチナ(後のイスラエル)に移り、ヘブライ大学で教授を務めた。1923年に刊行された主著『我と汝(Ich und Du)』において、ブーバーは人間が世界や他者と関わる根本的な様式として「我-それ(Ich-Es)」と「我-汝(Ich-Du)」という二つの関係を区別した。前者は対象を分析・利用・支配する関係であるのに対し、後者は相手を代替不可能な全き存在として迎え入れる相互的で直接的な出会いの関係である。\n\nブーバーはこの対話的関係の哲学を教育論にも展開し、真の教育とは、教師が一方的に知識や価値を注入することではなく、教師と学習者が互いを「汝」として尊重し合う人格的な出会いのなかで生起すると論じた。教育における関係性を「我-汝」の対話として捉えるこの思想は、教師と生徒の権力関係や一方向的な伝達モデルを超えて、双方向的で相互応答的な教育的関係のあり方を提起するものであった。\n\nブーバーの対話哲学は、20世紀後半以降の教育学において、対話的授業論やケアの倫理、応答的な教師-生徒関係の理論など、広範な領域に影響を与えている。知識や技能の伝達を超えて、人格と人格の出会いそのものを教育の本質と捉える視点は、効率性や成果主義に偏りがちな現代の教育を問い直す思想的資源として、今日なお参照され続けている。",
