    body: "ユルゲン・ハーバーマス(1929年生まれ)は、ドイツのデュッセルドルフに生まれた哲学者・社会学者であり、フランクフルト学派の批判理論を継承する第二世代の代表的思想家である。主著の一つ『コミュニケーション的行為の理論』(1981年)において、人々が互いの了解と合意を目指して行う「コミュニケーション的行為」と、目的達成のために他者を手段化する「戦略的行為」とを区別し、理想的発話状況のもとでの自由で対等な対話こそが、正当な社会的合意と民主的な公共圏を形成する基盤であると論じた。\n\nハーバーマスの理論は、直接教育論として展開されたものではないが、批判的教育学(クリティカル・ペダゴジー)をはじめとする教育理論に大きな理論的基盤を提供してきた。教育を単なる知識・技能の伝達過程としてではなく、教師と学習者、あるいは学習者同士が対等な立場で対話し、既存の権威や支配的な言説を批判的に検討しながら合意を形成していく過程として捉える発想は、ハーバーマスのコミュニケーション的合理性の概念に多くを負っている。\n\nまた、権力や利害関係によって歪められたコミュニケーションを批判的に照らし出すという彼の視座は、学校における隠れたカリキュラムや権力関係の分析、市民性教育における熟議民主主義の理論などにも援用されている。対話を通じた合意形成と自律的な主体形成を教育の中心に据える立場は、フレイレの批判的教育学とも思想的に響き合い、現代の教育哲学における重要な参照点となっている。",
