    body: "ベル・フックス(bell hooks、1952年-2021年)は、アメリカの黒人フェミニスト思想家・社会活動家であり、本名グロリア・ジーン・ワトキンズの名を小文字で記す筆名は、自身の個人的アイデンティティよりも思想の内容に注意を向けさせるための選択であった。彼女は人種・階級・ジェンダーが交差する抑圧構造を批判する著作を数多く著すとともに、大学での教育実践を通じて独自の教育論を発展させた。代表作『Teaching to Transgress: Education as the Practice of Freedom』(1994年、邦題『とびこえよ、その囲いを』)において、フックスは自らの教育理念を「関与の教育学(engaged pedagogy)」として提示した。\n\n関与の教育学とは、教師が知識を一方的に伝達する存在ではなく、学生とともに学びの共同体を築き上げていく実践を指す。フックスは、多くの大学の授業が形式的な知識伝達に終始し、学生・教員双方に無気力や退屈をもたらしていると批判し、これに対して、学生が自らの経験や声を教室に持ち込み、教師自身も自らの経験や弱さを開示しながら学生と対等に向き合う教育こそが、真に人々を解放へと導くと論じた。この立場は、パウロ・フレイレの批判的教育学から強い影響を受けつつ、人種・ジェンダーの視点を交差させて独自に発展させたものである。\n\nベル・フックスの思想は、大学教育における多様性・包摂性をめぐる議論や、学生の主体性と経験を重視するアクティブラーニング型の授業実践に大きな影響を与えている。知の生産と伝達における権力関係を問い直し、教室を自由の実践の場として捉えるその思想は、現代の高等教育における教育学のあり方を再考する上で重要な参照点となっている。",
