    kana: "ふ",
    categories: ["philosophy", "sociology"],
    summary:
      "フランスの哲学者ミシェル・フーコー(1926-1984)が『監獄の誕生』で展開した権力論。近代の学校を、時間割や試験を通じて従順な身体を作り出す規律訓練装置として批判的に分析した。",
    body: "ミシェル・フーコー(1926年-1984年)は、フランスの哲学者であり、知と権力の関係を歴史的に分析する独自の「系譜学」的方法によって、精神医学・監獄・性の歴史など多様な主題を論じた。主著の一つ『監獄の誕生――監視と処罰』(1975年)において、フーコーは近代社会における権力のあり方が、身体を直接的に処罰する前近代的な権力から、身体を規律づけ従順にする「規律訓練権力」へと変容したことを論じた。その象徴として、哲学者ジェレミー・ベンサムが構想した監視塔を中心に配置する円形の監獄建築「パノプティコン」を取り上げ、常時監視されているという意識そのものが人々に自己規律を内面化させる仕組みを分析した。\n\nフーコーはこの規律訓練の技術が監獄のみならず、軍隊・工場、そして学校にも及んでいったと指摘する。時間割による時間の管理、座席配置による空間の統制、繰り返しの訓練と反復練習、そして試験による絶え間ない評価と序列化といった近代学校の日常的な仕組みは、生徒たちを「従順な身体」へと形づくる規律訓練の装置として機能していると分析された。この視座は、学校を単なる知識伝達の場としてではなく、権力が主体を形成する装置として批判的に捉え直す教育社会学的分析に大きな影響を与えた。\n\nフーコーの規律訓練権力論は、教育における評価・管理・規範化の作用を批判的に問い直す視点を提供し、隠れたカリキュラム論や学校における権力関係の分析、さらにはICTを用いた学習履歴の収集・可視化がもたらす新たな管理のあり方を検討する現代の議論にも継承されている。",
