    body: "ビルドゥング(Bildung)は、ドイツ語の動詞「bilden(形づくる、形成する)」から派生した名詞であり、日本語では「陶冶」あるいは「教養」「人間形成」などと訳される教育学の基礎概念である。18世紀の啓蒙主義期のドイツにおいて、人間が単に外部から知識を注入されるだけの受動的な存在ではなく、自己の内に備わった理性・感性・道徳性などの諸能力を、学びと経験を通じて自ら全面的に開花させていく能動的な自己形成の過程として概念化された。その起源は16世紀以来の神秘主義的な「神の似姿への形成」という思想にまで遡るとされる。\n\nビルドゥングの理念は、フンボルトらドイツ新人文主義の教育思想において特に重要な位置を占め、専門的な職業訓練(アウスビルドゥング)とは区別される、人格全体の調和的な発展を目指す教養教育の理想として展開された。単なる学識の多寡や職業的技能の習得にとどまらず、一定の文化的理想のもとで知・情・意のあらゆる側面にわたる精神的能力を洗練させることこそが、真の教育の目的であるとされたのである。この理念は、教育の内容や方法を細かく分節して捉える「形式陶冶」対「実質陶冶」の論争など、教育学における陶冶論の展開にもつながっている。\n\nビルドゥングの概念は明治以降の日本にも輸入され、「教養」という語を通じて大正期の教養主義など日本の知識人文化にも大きな影響を与えた。効率性や成果を重視する現代の能力主義的な教育観に対し、人格の全面的で調和的な発達を教育の本質とみなすビルドゥングの理念は、教育とは何かを根本から問い直す思想的視座として今日も参照され続けている。",
