    body: "パイデイア(paideia)は、古代ギリシア語で「子ども(パイス)」を語源とし、もともとは子どもを訓育して一人前の成人に育てることを意味する語であった。しかし古代ギリシアにおいてこの語は、狭義の子どもの教育にとどまらず、次第に成人をも含めた人間形成全般、さらには共同体が共有する教養・文化・伝統の総体を指す広範な概念へと展開していった。今日、英語の「pedagogy(教育学)」の語源となっているように、パイデイアは西洋における教育概念の原型をなすものである。\n\nドイツの古典学者ヴェルナー・イェーガーは、大著『パイデイア――ギリシアにおける人間形成』(1934年-1947年)において、古代ギリシアの文学・哲学・政治思想全体を貫く根本理念としてパイデイアを位置づけた。イェーガーによれば、ギリシアにおける教育とは個人の私的な事柄ではなく共同体全体の事業であり、共同体はその成員となる新たな個人を、共同体が共有する価値や規範に沿って意識的に形成しようとする不断の努力のなかにパイデイアが存在するとされる。ホメロスの叙事詩における英雄的卓越性(アレテー)の理想から、ソフィストによる弁論術教育、そしてプラトン・アリストテレスによる哲学的な人間形成論に至るまで、パイデイアの理念は古代ギリシア思想史全体を貫く軸として描かれた。\n\nパイデイアの概念は、単なる知識・技能の伝達を超えて、人間が共同体の文化的理想のもとで人格・教養を全面的に形成していく過程を捉える視座として、後のローマの人文教養(フマニタス)や近代ヨーロッパの教養(ビルドゥング)概念にも継承された。今日のリベラルアーツ教育や全人教育の理念の源流をたどるうえでも、パイデイアは重要な参照概念である。",
