    body: "児童中心主義とは、教育の目的・内容・方法を、大人や社会の側の都合ではなく、児童・子どもの発達段階や個性、自発性を出発点として決定しようとする教育上の立場である。19世紀末から20世紀初頭にかけて、主としてアメリカやドイツを中心に唱えられ、それまで主流であった教師や教科書が一方的に知識を注入する伝達型の教育を批判し、子どもが本来持っている成長への力や興味・関心を信頼し、これを引き出し伸ばすことを教育の中心に据えるべきだとする考え方が「新教育運動」として世界的に広がっていった。\n\nこの思想の理論的な基盤には、ルソーの自然主義的教育論や、子どもの経験を通じた学びを重視したデューイの教育哲学などが存在する。デューイが「子どもが太陽となり、その周囲を教育のさまざまな装置が回転することになる」と表現したように、教育活動全体の重心を大人(教師)から子どもへと転換させる発想が、この時期の教育改革運動に共通する特徴であった。\n\n日本においては大正時代に、従来の画一的・注入的な教育を「旧教育」として批判し、子ども中心の理想の教育を求める実践が各地で展開された。文部官僚であった澤柳政太郎が創設した成城小学校や、伊藤長七らによる自由主義教育の実践などがその代表例であり、これらは「大正自由教育(大正新教育)」と呼ばれる潮流を形成した。児童中心主義の理念は、その後の日本の教育実践、とりわけ生活教育や個に応じた指導の思想的源流の一つとなっている。",
