    body: "大正教養主義とは、大正時代(1912年-1926年)の日本において、旧制高等学校や大学の学生を中心とするエリート層のあいだに広まった思想的潮流である。哲学者の阿部次郎(1883年-1959年)がその代表的な担い手とされ、彼が1914年に発表した『三太郎の日記』は、当時の中学・高校生にとって必読の書とされるほどの影響力を持った。大正教養主義の中核には、単なる知識の集積としての「学識」とは異なり、文学・哲学・芸術などの古典を読書によって深く咀嚼することを通じて、自己の人格を陶冶し高めていくべきだとする理念があった。\n\nこの思想潮流を担ったのは、ドイツ観念論やロマン主義の影響を受けた人格主義的な哲学であり、単に立身出世や実利のための学問ではなく、「生」や「愛」といった内面的な充実を求める自己探求的な読書実践として展開された。岩波書店による岩波文庫・岩波講座などの出版活動は、こうした教養主義的な読書文化を支える重要な基盤となり、「岩波文化」とも呼ばれる知的風土を形成した。\n\n大正教養主義は、旧制高校を中心としたエリート学生文化として一時代を築いたが、戦後には大衆化した高等教育のなかで次第にその基盤を失い、「教養主義の没落」として社会学的にも分析されるようになった。しかし、実利や資格取得に偏らず、古典との対話を通じて人格を陶冶するという理念そのものは、ドイツのビルドゥング概念を日本的に受容・展開したものとして、日本の高等教育・教養教育のあり方を考える上で今なお重要な参照点となっている。",
