    body: "カール・ロジャーズ(1902年-1987年)は、アメリカの心理学者であり、人間性心理学(ヒューマニスティック心理学)の代表的な創始者の一人である。彼はカウンセリングの領域において、セラピストが指示や解釈を与えるのではなく、クライエントの語りをありのままに受容し、共感的に理解する態度を重視する「来談者中心療法(クライエント中心療法)」を提唱した。この理論の根底には、人間は本来、自ら成長し自己を実現しようとする傾向(自己実現傾向)を備えているという人間観がある。\n\nロジャーズは1960年代以降、この来談者中心の理念を教育の領域にも拡張し、1969年の著書『学習の自由(Freedom to Learn)』において「学習者中心教育(person-centered / student-centered education)」の構想を提示した。ここでは、教師の役割は知識を一方的に教え込む権威者としてではなく、学習者が自ら意味のある学びを主体的に構築していく過程を側面から支える促進者(ファシリテーター)として捉え直される。教師には、学習者をありのままに受け入れる「無条件の肯定的関心」、学習者の内面に共感的に寄り添う「共感的理解」、そして教師自身が飾らず一致した態度で接する「自己一致」という三つの基本的態度が求められるとされた。\n\nロジャーズの学習者中心教育論は、知識の伝達を中心とする伝統的な教授法に対して、学習者の主体性・自己決定・情緒的な安心感を重視する教育観として、その後のアクティブラーニングやファシリテーション型授業、カウンセリングマインドを生かした生徒指導のあり方などに大きな影響を与えている。",
