    body: "ヨハン・ゴットリープ・フィヒテ（1762〜1814）は、カントの影響を受けたドイツ観念論を代表する哲学者です。彼の教育思想の代表的な表明が、1807年12月から翌年にかけてフランス軍占領下のベルリン学士院で行われた14回の連続講演『ドイツ国民に告ぐ』です。敗戦と占領という危機のなかで、国民の再生は新しい教育によってこそ可能になると訴えました。\n\nフィヒテが構想したのは、一部の上層階級だけでなく国民全体を対象とする教育です。従来の教育は知識を外から詰め込むにとどまっていたと批判し、子どもの内面にある精神的な活動性を引き出し、自ら考え意志する人間を育てることを求めました。その手がかりとして高く評価したのが、スイスの教育実践家ペスタロッチの教育法です。フィヒテはペスタロッチの方法を国民教育の基礎に据えることを構想しました。\n\nこの講演は、近代国民国家における公教育の役割を早い時期に理論化したものとして知られ、のちのドイツの教育改革や国民教育論に影響を与えました。一方で、教育を国民の統合や国家の再建と強く結びつける発想は、のちに国家主義的に読まれる面もあり、評価は分かれます。教育と国家・国民形成の関係を考える際の古典的な論点を提供する文献です。",
