    body: "ゲオルク・ケルシェンシュタイナー（1854〜1932）はミュンヘン生まれのドイツの教育者・教育理論家です。数学教師を経て1895年にミュンヘンの公立学校の視学官となり、1918年からは亡くなるまでミュンヘン大学教授を務めました。教育実践と理論研究の双方に関わり、ドイツの職業教育の発展を主導した人物としても知られます。\n\n彼の中心的な主張が「労作学校（Arbeitsschule）」です。知識を教師から生徒へ伝えるだけの「書物学校」を批判し、作業場や実験などでの手仕事的な作業を学習の中心に据えました。作業を通じて、技術的な能力だけでなく、正確さ、勤勉さ、責任感といった精神的・道徳的な力も育つと考えたのです。主著『労作学校の概念』は1912年に刊行されました。\n\nもう一つの柱が公民教育です。1901年に懸賞論文「ドイツ青年の公民教育」を発表し、作業共同体での協同の経験を通じて、国家に奉仕する有能な公民を育てることを論じました。この公民教育論は有機体的な国家観に立つものでした。彼の学説は大正から昭和初期の日本の教育界にも大きな影響を与え、労作教育への関心を高めました。",
