    summary:
      "ディルタイの流れをくむ教育学者ノールが、教育者と子どもの人格的な結びつきを教育の根本に据えた「教育的関係」の理論です。精神科学的教育学の中核概念とされます。",
    body: "ヘルマン・ノール（1879〜1960）は、ベルリンに生まれたドイツの教育学者で、哲学者ディルタイの学徒です。ディルタイは人間の生や歴史を理解（解釈）によってとらえる精神科学を提唱し、その立場を教育に適用したのが精神科学的教育学です。ノールはその代表者で、リット、シュプランガー、ヴェーニガーらとともにこの学派の中心を担いました。\n\nノールの「教育的関係」は、教育者の被教育者に対する人格的な関係として定義されます。教育は制度や技術の問題である前に、成熟した大人が成長途上の子どもに、その子自身のために向き合う関係だというのです。この概念自体はディルタイも大学の講義草稿で論じていましたが、理論として明確に打ち出したのはノールでした。\n\nノールがこの理論を磨いた背景には、20世紀初頭の改革教育学運動、とくに青年運動や社会的教育学への深い関与がありました。教育的関係論は、教育を人格と人格の出会いとしてとらえる立場として、のちの教育人間学や日本の教育哲学にも影響を与えています。なお、ナチズム期のノールの態度については研究者の間で評価が分かれています。",
