    summary:
      "ドイツの哲学者・教育学者ボルノウは、実存哲学や生の哲学を踏まえて教育を人間学的に考察し、教育的雰囲気や非連続的な教育形式などの概念を示しました。",
    body: "オットー・フリードリヒ・ボルノウ（ボルノー、1903〜1991）は、当時プロイセン領だったポンメルン州都シュテッティンに教員の家に生まれたドイツの哲学者・教育学者です。もともとは物理学を学び、その後哲学に転じて、ギーセン、キール、マインツ、テュービンゲンの各大学で哲学と教育学の教授を務めました。生の哲学、現象学、実存哲学との対決を通じて、人間とは何かを問い続けました。\n\n教育学での大きな功績は、実存哲学の知見を教育に取り入れたことです。従来の教育学が、連続的な発達や計画的な形成を前提にしていたのに対し、ボルノウは、出会い、危機、覚醒、訓戒といった、人間の生に起こる非連続的な出来事が教育にとって本質的であると論じました。教育は計画どおりに進む営みだけでなく、人間の生の転機に関わるものだというのです。\n\nまた、教育者と子どもの間の関係を、情緒的な基本条件や感じ取られる質としてとらえ直し、「教育的雰囲気」という概念を提示しました（『教育的雰囲気』は1964年刊）。さらに、人が安心して世界に住まうための基盤を「被護性（Geborgenheit）」の概念で論じています。教育人間学の代表的な論者として、日本でも広く紹介されています。",
