    body: "ハンナ・アーレント（1906〜1975）は、全体主義や公共性を論じたことで知られるドイツ出身の政治思想家です。彼女の教育論は、論文「教育の危機」にまとまっています。この論文は1958年にアメリカの雑誌『パルチザン・レヴュー』に発表され、のちに論文集『過去と未来の間』（1961年）に収められました。当時のアメリカの公民権運動をめぐる問題への関心が、教育への考察の契機の一つになったとされています。\n\n議論の中心にあるのが「誕生性（natality）」の概念です。人間は絶えず新しい者として世界に生まれてきます。教育とは、こうした新参者である子どもを、既存の世界の中へ迎え入れ、その世界に「くつろいで」いられるよう導く営みだと、アーレントは考えました。同時に、子どもの持つ新しさや、世界を更新する力を奪ってはならないとも述べています。\n\nそのため彼女は、教育は保守的でなければならないと主張しました。これは、世界を守る責任を大人が引き受けることで、子どもの新しさを守るという意味です。子どもに対しては世界についての責任を、世界に対しては子どもの新しさへの責任を負う、という二重の責任が教育者に求められます。権威や伝統が失われた現代において、教育の意味を根本から問い直す論考として、現在も広く参照されています。",
