    summary:
      "数学者・哲学者ホワイトヘッドが示した教育論です。「不活性な観念」を批判し、ロマンス・精密・一般化という教育のリズムと、生徒の自己発達の重視を説きました。",
    body: "アルフレッド・ノース・ホワイトヘッド（1861〜1947）は、イギリスの数学者・哲学者で、のちにアメリカのハーバード大学でも教えました。教育論の代表作は『教育の目的』です。表題の講演はイギリス数学協会の会長講演として1916年に行われたもので、他の論文とともに論文集『The Aims of Education and Other Essays』（1929年）に収められました。\n\n彼の教育論の中心にある批判対象が「不活性な観念」です。頭の中に受け入れられるだけで、活用も検証もされず、新しい組み合わせにも使われない観念のことで、ホワイトヘッドはそうした観念で満たされた教育は役に立たないだけでなく有害だと考えました。そのため、教える科目を絞って、教えることは徹底して教えるという二つの戒律を掲げ、知識の断片の寄せ集めは教養ではないと述べました。\n\nさらに彼は、教育を「ロマンス」「精密」「一般化」という三つの段階が繰り返されるリズムとしてとらえました。まず対象への興味と驚きが生まれ、次に正確な知識や技能を身につけ、最後にそれを広い文脈に位置づけて活用する、という流れです。教育の目的は生徒の自己発達を刺激し導くことであるとする立場は、日本でも自己教育を重んじる議論として紹介されています。",
