    body: "1930年代のアメリカでは、デューイらの進歩主義教育が児童中心の傾向を強めるなかで、学力低下や教育内容の弱体化を懸念する立場が現れました。その代表が本質主義（エッセンシャリズム）と永続主義（パレニアリズム）です。両者は進歩主義への批判という点で共通していますが、主張の中身は異なります。\n\n本質主義は、文化遺産のうち社会の維持と発展に不可欠な基礎的内容を、体系的に教えるべきだとする立場です。1938年に本質主義運動が教育管理者協会の年次総会で立ち上げられ、その場で教育学者バグリーが「本質主義者の綱領」と題する講演を行いました。これに対してデューイやキルパトリックらは応答を行っています。もっとも、バグリーを本質主義者と一括りにすることは実態を単純化しすぎているという指摘もあります。\n\n永続主義は、人間の本性は変わらないので、時代を超えて価値を持つ古典の学習が教育の中心であるとする立場です。ハッチンズは1936年の『アメリカの高等教育』で、実用主義に傾いた高等教育を批判しました。ハッチンズとアドラーは『西洋の偉大な書物』（全54巻、1952年）の編集を主導し、アドラーは1982年の『パイデイア提案』で、すべての子どもに同質の教育を与えるべきだと主張しました。これらの対立は、教育内容を誰がどう決めるのかという現代の課題にもつながっています。",
