      "19世紀末から20世紀初頭に欧米で広がった、伝統的な学校教育を批判して子どもの自発性や生活を重んじる教育改革運動です。日本の大正新教育にも影響を与えました。",
    body: "新教育運動は、19世紀末から20世紀前半にかけてヨーロッパやアメリカで広がった教育改革の総称です。画一的な知識の詰め込みや教師中心の授業、厳しい規律を批判し、子どもの個性や自発的な活動、生活との結びつきを重んじる教育を目指しました。国によって呼び名は異なり、ドイツの改革教育学、アメリカの進歩主義教育などもこの流れに含まれます。\n\n運動の先駆けの一つが、1889年にセシル・レディがイギリスのダービーシャーに開いたアボッツホルム校です。知的な学習に、身体運動、手作業、芸術などを組み合わせた全人的な教育を行い、ヨーロッパ各地で模倣されました。とくにドイツでは、レディの学校に学んだリーツが田園教育舎（ラントエルツィーウングスハイム）を設立し、自然の中での共同生活と労作を重視する教育を広めました。\n\n新教育運動は、教育の方法や学校のあり方を大きく変える契機となり、のちには国際的な連携も生まれました。日本では大正期に、自由教育や労作教育、合科学習などの実践が各地の私立学校や師範学校附属小学校で試みられ、大正新教育として展開しました。他方、子どもの自由と社会の要請をどう両立させるかという課題は、現在も教育思想の重要な論点として残っています。",
