    body: "貝原益軒（1630〜1714）は、福岡藩に仕えた江戸前期の儒学者で、福岡藩士の子として福岡城下に生まれました。朱子学を学びつつ、本草学（薬物や動植物の学問）や地誌、民衆の生活に役立つ実用の学問にも力を注ぎ、日常の暮らしに即した平易な著作を多く残しました。\n\n教育に関する代表作が『和俗童子訓』です。日本で初めて現れた教育論書と位置づけられ、民衆の日常生活に役立つ学問を志す益軒の姿勢がよく表れた、平易な訓戒に満ちています。とくに特徴的なのが、生まれたときから二十歳に至るまで、成長の段階に応じた教え方を細かく立てた「随年教法」です。年齢ごとの発達に合わせて教育の内容と方法を考えるという発想を、体系的に示した点が高く評価されています。また、読書の重要性や、幼いうちから正しい習慣を身につけさせることの大切さも説きました。\n\n益軒の教育論は、近代に入って教育学者の三宅米吉が『益軒ノ教育法』で再評価したことでも知られます。子どもの成長段階を踏まえて教えるという考え方は、近代の発達理論や児童研究につながる視点として、現在でも日本教育思想史で重要な位置を占めています。",
