    body: "広瀬淡窓（1782〜1856）は、豊後国日田（現在の大分県日田市）の儒学者・教育者です。1817年（文化14年）に塾を開き、これが咸宜園として発展しました。咸宜園は明治期まで続いた代表的な私塾で、淡窓は1856年（安政3年）に園内の春秋園で亡くなっています。\n\n咸宜園の教育の特色は、教育制度の整備にありました。入門者の年齢、学歴、身分を問わないとする方針（三奪法）をとり、塾生をすべて平等に扱いました。学習は漢学を中心に段階的に整えられた教育課程にもとづいて進み、整然とした進級規定や、毎月の成績を評価して席次を定める月旦評などの細かな評価の方法は、当時の私塾としては最も進んでいたと評されています。知識の教授だけでなく、人間形成としての訓育を重んじ、塾生が当番を担う自治的な塾舎生活が営まれたことも特徴です。\n\n淡窓の思想の根底には、天を敬い、天の理にしたがって生きるという敬天の考え方がありました。身分制社会にありながら、能力と努力によって評価する仕組みをつくったことは、のちの近代学校の発想に通じる面があります。咸宜園は多くの人材を輩出し、藩校や寺子屋とは別の、江戸時代の民間高等教育の到達点として今日でも研究されています。",
