    summary:
      "奈良女子高等師範学校附属小学校の主事として「奈良の学習法」を築いた木下竹次の教育思想です。学習者の生活から出発する学習と、教科を総合する合科学習を提唱しました。",
    body: "木下竹次（1872〜1946）は、大正期の新教育を代表する教育者の一人です。奈良女子高等師範学校附属小学校の主事を務め、大正8年（1919年）から昭和15年（1940年）にかけて「学習法」の基礎を築き、全国に広めました。主著『学習原論』では、学習は学習者が生活から出発し、生活によって生活の向上をはかるものだという考えを示しました。\n\n彼が1920年から行った総合的な学習が「合科学習」です。教科ごとに分断された学習ではなく、子どもの生活に根ざした題材のもとに、複数の教科を総合して学ばせるものでした。すべての教科を含む「全科的合科学習」と、一つまたは少数の教科を扱う「一科合科学習」とに分けられ、すべてを合科で行うのではなく、児童の状況に応じて柔軟に取り入れる考え方でした。\n\n学習の過程は、独自学習から相互学習、そして再び独自学習へと進むものとして構想されました。まず子どもが自分で学び、次に仲間と学び合い、最後にもう一度自分の学びに戻るという流れで、児童が互いに交流しながら学ぶことが目指されました。この実践は全国から参観者を集め、「奈良の学習法」として奈良女子大学附属小学校に受け継がれています。のちの生活科や総合的な学習の時間にもつながる先駆的な試みとして評価されています。",
