    summary:
      "戦後日本を代表する教育哲学者村井実が展開した、「善さ」を軸とする教育論です。教育を子どもを善くする営みととらえ、道徳教育の論理を独自に体系化しました。",
    body: "村井実は1922年、佐賀県に生まれた教育哲学者です。1944年に広島文理科大学（現在の広島大学）を卒業し、1949年に慶應義塾大学文学部に着任、1961年に教授となり、1987年の退職まで多くの著作を残しました。戦後昭和期の慶應義塾における教育学研究の中心を担い、その理論は「村井教育学」と呼ばれます。\n\n村井の教育哲学の中心概念が「善さ」です。主著『「善さ」の構造』（1978年）をはじめ、『道徳は教えられるか』（1967年）、『教育学入門』（1976年）、『道徳教育の論理』（1981年）などで、教育とは人を善くしようとする営みであり、その目標は「善さ」にあると論じました。村井は「善さ」を、他者との間でどこまでも同意を求めながらつくり出していく一元的な価値としてとらえました。また、学校教育が本来は「子どもたちを善くし国を善くしよう」としてはじめられたのに、その目的が「善さ」から「快さ」へすり替わったと指摘しています。\n\nこうした考えにもとづき、あらかじめ決まった理想の人間像を子どもに当てはめるのではなく、よりよい生き方を探究し続ける過程そのものを重んじる道徳教育を構想しました。「善さ」の論については批判的検討も重ねられており、日本の教育哲学における重要な論争点であり続けています。",
