    body: "斎藤喜博（1911〜1981）は、群馬県玉村町に生まれた教育実践家です。1952年、41歳で佐波郡島村の島小学校長となり、以後11年にわたって学校づくりに取り組みました。子どもが持つ無限の可能性を引き出し高めることこそ教師の仕事であると説き、その実践は「島小教育」と呼ばれます。実践の記録は『島小研究報告』にまとめられ、1958年には教員の共同執筆による『未来につながる学力』も刊行されました。\n\n島小の特徴は、授業を創造的な営みとしてとらえる姿勢にありました。教材を深く追求し、教師と子どもが真剣に向き合うことで、子どもの可能性を伸ばす授業の思想と方法を生み出したと評価されています。また、島小は公開研究会を積極的に開き、11年間に8回、のべ約1万人の教師や研究者、行政関係者、芸術家などが参加したとされます。1955年12月の第1回公開研究会のテーマは「解放と創造」でした。\n\n斎藤は島小の後、境東小学校（1963〜64年）、境小学校（1964〜69年）でも校長を務め、1969年の定年退職後は各地の大学で教えました。1966年には『可能性に生きる』を著しています。教師の専門性や学校づくり、授業の質をどう高めるかという問いに、戦後日本の現場から答えを出そうとした実践的教育思想として、今日でも授業研究の古典的な事例として参照されています。",
