    body: "ガート・ビースタは、現代を代表する教育理論家の一人です。2010年に著書『Good Education in an Age of Measurement: Ethics, Politics, Democracy』を刊行し、邦訳は『よい教育とはなにか—倫理・政治・民主主義』（藤井啓之・玉木博章訳、白澤社）として出ています。その核心にある主張は、測定可能な成果や効率ばかりが重視される風潮のなかで、教育の目的についての問いが失われてしまったという批判です。\n\nビースタは、教育の目的に関する議論の枠組みとして、教育の三つの機能を示しました。資格化は、職業や社会生活で何かができるよう準備する機能です。社会化は、既存の文化や価値、規範のなかへ新しい世代を導き入れる機能です。主体化は、自律した思考と行為ができる、その人自身になることに関わる機能で、既存の秩序に従うだけでなく、別様のあり方を可能にする側面を含みます。ビースタは、とくに主体化が教育の本質的な構成要素であるべきだと主張しました。\n\nまた、教育が「学習」の言葉で語られる傾向を「学習化」と呼んで批判しています。何を、何のために、誰から学ぶのかという問いを抜きにして学習だけを強調すると、教育の方向性を論じにくくなるという指摘です。主体化の概念には、レヴィナスやアーレントなどの思想が参照されており、難解だとされます。一方で、主体化は計画どおりに生み出せるものではないという点には、批判的な検討も向けられています。",
