    summary:
      "オランダの教育学者ランゲフェルトは、現象学的な方法で子どもと教育の営みを記述し、「子どもの人間学」を構想した教育人間学の代表的論者です。",
    body: "マルティヌス・ヤン・ランゲフェルト（1905〜1989）は、第二次世界大戦後のオランダの教育学を代表する人物で、日本語文献では「ランゲフェルド」などの表記の揺れもあります。シュテルン、コーンスタム、リット、そしてフッサールの現象学など多様な思想的源流を土台に、独自の教育学を築きました。戦後のドイツ語圏およびオランダの教育人間学を代表する一人とされています。\n\nランゲフェルトの特徴は、子どもを小さくてもすでに「人間」であるとみなす点です。子どもは人と人との関係のなかにありながら、大人の助けなしには生きられない存在であると考え、その子どもと、教育の責任を自覚した大人との関係を、現象学的な方法で明らかにしようとしました。具体的には、子どもを育てる責任ある者が何をなすべきかを、状況の分析によってとらえるという、実践的・規範的な教育学を目指しました。\n\n日本でも、教育人間学や教育における現象学の議論で繰り返し参照されてきました。2011年には、和田修二・皇紀夫・矢野智司編『ランゲフェルト教育学との対話——「子どもの人間学」への応答』が玉川大学出版部から刊行されています。子どもをどう理解し、大人の責任とは何かを考える際の基本的な手がかりを与える思想家です。",
