      "インドの詩人タゴールが、シャンティニケタンに開いた学園とヴィシュヴァ・バーラティ大学で実践した教育思想です。自然との調和と自由な探究、国際的な相互理解を重視しました。",
    body: "ラビンドラナート・タゴール（1861〜1941）は、ベンガル出身の詩人・思想家です。1913年にアジア人として初めてノーベル文学賞を受賞したことで知られますが、教育者としても重要な足跡を残しました。1901年12月22日、ベンガル地方のシャンティニケタンに学校を開きます。当初はブラフマチャリヤ・アシュラマと呼ばれ、古代インドのグルクル（師の家で共に暮らして学ぶ制度）をモデルとしていました。\n\nこの学園では、授業の多くが木の下などの戸外で行われ、体罰や形式的な規律はほとんどなく、芸術や音楽が重視され、試験や成績評価も重んじられませんでした。タゴールの教育観は、教科書中心の学習よりも、宗派にとらわれない国際主義の精神と、理性にもとづく自由な探究、そして実際的な社会の進歩を重視するものでした。学生の想像力と思考の自由を育てることを目的としたのです。\n\n1921年には、人類の一体性を意味する「ヴィシュヴァ・バーラティ」の名のもとに、学園に国際大学が併設されました。1920年代前半には、近くのスルルでスリニケタンという農村再建の取り組みも始まり、エルムハーストらが参加しました。タゴールの学園は現在、ユネスコの世界遺産にも登録されています。西洋近代の学校制度とは別の道を示した教育思想として、新教育運動やガンディーの教育論とあわせて学ばれています。",
