    body: "マハトマ・ガンディー（1869〜1948）は、インド独立運動の指導者であると同時に、植民地教育に代わる国民教育を構想した教育思想家でもあります。1937年にワルダーで開かれた全インド国民教育会議で、「ベーシック・エデュケーション（基礎教育）」を提唱しました。その柱は、7年間の義務教育、手工芸を教育の方法とすること、そして母語を教授言語とすることでした。\n\nもっとも重要な原理は「自給」の考え方です。手工芸などの生産的な作業を通じて学ぶことで、子どもの生活能力を高めるとともに、インド社会全体の経済的・精神的な自立を促すことが目指されました。1937年には、州議会が教育を所管するようになったことも、この構想を具体化する機会となりました。\n\nガンディーは1945年に、この枠組みを生涯教育へと広げて「ナイ・タリム（新しい教育）」を確立しました。すべての教育段階で自給の考えを重視し、農村再建と結びつけたのが特徴です。しかし、独立後のインド政府は、農村再建よりも工業を重視したため、ナイ・タリムには必ずしも賛成しませんでした。それでも、労働と学習を結びつける発想や、植民地的な知の体系を問い直す視点は、のちのインドの教育思想や開発教育に受け継がれています。",
