    body: "アントン・セミョーノヴィチ・マカレンコ（1888〜1939）は、ウクライナ出身のソビエトの教育者・作家で、ブリタニカ百科事典はソ連で最も影響力のあった教育理論家と位置づけています。革命後の混乱で家を失い、犯罪集団として各地をさまよっていた子どもたちのために、1920年ごろにポルタヴァ近郊で更生施設「ゴーリキー・コローニア」を設立し、運営しました。のちにジェルジンスキー・コムーナの責任者も務めています（就任時期は資料により異なります）。\n\n彼の教育論の中心は、教育は集団を基盤とし、集団を通じて行われるべきだという考え方です。具体的には、子どもたちの班という単位や、子どもが運営に参加する階層的な自治組織をつくり、共同の労働と生活のなかで規律と責任を育てようとしました。個性が集団によって損なわれるという批判に対しては、社会主義社会では集団の利益と個人の利益は一致すると主張しました。\n\nこれらの実践は、代表作『教育詩』（1930年代半ばの執筆とされる）に描かれ、世界各国で翻訳されました。日本でも紹介と研究が進められています。他方、マカレンコの方法がのちに画一的な思想統制に転用されたという批判もあり、歴史的評価は分かれています。集団と個人、自治と規律の関係を考える上で、今なお議論される教育思想です。",
