    body: "デシデリウス・エラスムス（1466年頃〜1536）は、オランダの人文学者で、古典文学の校訂や注解、聖書の原典批判、カトリック教会批判などを行い、その名声は全ヨーロッパに及びました。風刺文学の傑作『愚神礼讃（痴愚神礼讃）』は代表作として知られます。教育についても数多く論じ、北方ルネサンスの人文主義教育を代表する存在です。\n\n教育に関する主な著作には、『学習方法論』（1511〜12年ごろ）、『キリスト者の君主の教育』（1516年ごろ刊とされる、後のスペイン王カルロス1世となるブルゴーニュ公カルルに献呈）、『幼児教育論』（1529年にフローベン社から刊行）があります。エラスムスが提案した教育課程は、ギリシア・ローマの古典に通じて雄弁であり、同時に福音の精神を宿したキリスト教的人文主義者を育てることを目指すものでした。\n\n『幼児教育論』では、早期から自由な教養教育を行うべきだと論じ、暗記中心の学習や体罰に反対して、遊びを取り入れた教え方を支持しました。ここでの「自由な」教育とは、学ぶ者を自由にし、独立して考える力を与える教育を意味します。また、道徳教育と学習との結びつきはキリスト教的人文主義の重要な特徴とされます。のちのコメニウスやロックらの教育論の背景をなす思想として、教育思想史の出発点の一つに位置づけられています。",
