    body: "アメリカの物理学者・科学史家トーマス・クーンは、1962年の主著『科学革命の構造』において、科学の発展を客観的知識の直線的で累積的な積み重ねと捉える伝統的な科学観を根本から覆した。\n\nクーンは、ある時代の科学者集団に共有された思考の枠組みを「パラダイム」と呼んだ。通常時はパラダイムに基づく「通常科学」として問題解決が進むが、説明困難な変則事象の蓄積によって危機が生じ、根本的に異なる新しい枠組みへと飛躍する「パラダイム転換（科学革命）」が起きると論じた。異なる枠組みの間には共通の比較尺度が成り立たない共約不可能性を指摘し、知の社会的性格を明らかにした。\n\n知識を絶対不変のものと見なさないクーンの視座は、構成主義的な教育理論を大きく前進させ、現代の科学教育において児童生徒が自らの素朴な概念を自覚的に乗り越える概念変革の指導法に深い示唆を与えている。",
